import { loadUser } from "./loader.js";

// 记忆化缓存：同一个 id 只真取一次，不同 id 互不影响
const cache = new Map();

export async function getUser(id) {
  if (cache.has(id)) {
    return cache.get(id);
  }
  const promise = loadUser(id);
  cache.set(id, promise);
  return promise;
}

export function resetCache() {
  cache.clear();
}
